import java.util.Scanner;

public class Main {

    public static int findGCD(int a, int b) {
        int gcdCandidate = Math.max(a, b);
        while (true) {
            if (a % gcdCandidate == 0 && b % gcdCandidate == 0)
                break;
            gcdCandidate--;
        }
        return gcdCandidate;
    }

    public static void getDiff(double x, double y, double a, double b, double[] result) {
        result[0] = Math.abs(x * b - y * a);
        result[1] = y * b;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double x = scanner.nextDouble();
        double y = scanner.nextDouble();
        double n = scanner.nextDouble();

        if (n > y) {
            int g = findGCD((int) x, (int) y);
            if (g != 1) {
                x /= g;
                y /= g;
            }
            System.out.println(x + "/" + y);
            scanner.close();
            return;
        }

        double minRatio = 1e9;
        int aBest = 0, bBest = 0;

        for (double b = n; b >= 1; b--) {
            double a = (x * b) / y;
            if (Math.floor(a) == a) {
                aBest = (int) a;
                bBest = (int) b;
                break;
            } else {
                double[] diffResult = new double[2];

                getDiff(x, y, Math.floor(a), b, diffResult);
                double num = diffResult[0];
                double den = diffResult[1];
                double ratio = num / den;

                if (ratio < minRatio) {
                    minRatio = ratio;
                    aBest = (int) Math.floor(a);
                    bBest = (int) b;
                } else if (ratio == minRatio && (int) Math.floor(a) < aBest) {
                    aBest = (int) Math.floor(a);
                    bBest = (int) b;
                }

                getDiff(x, y, Math.ceil(a), b, diffResult);
                num = diffResult[0];
                den = diffResult[1];
                ratio = num / den;

                if (ratio < minRatio) {
                    minRatio = ratio;
                    aBest = (int) Math.ceil(a);
                    bBest = (int) b;
                } else if (ratio == minRatio && (int) Math.ceil(a) < aBest) {
                    aBest = (int) Math.ceil(a);
                    bBest = (int) b;
                }
            }
        }

        int g = findGCD(aBest, bBest);
        if (g != 1) {
            aBest /= g;
            bBest /= g;
        }
        System.out.println(aBest + "/" + bBest);
        scanner.close();
    }
}
